/**
 * Princeton WordNet 2.1 ILI registry (SRS §13.2).
 *
 * Loaded once from data/wordnet21-ili.json (generated by
 * scripts/build-wordnet21-ili.mjs from the official WordNet 2.1 package).
 * Provides English-word + POS → ILI lookup for non-technical contributors.
 */
import "server-only";
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";

export type WnPos = "n" | "v" | "a" | "r";

export interface IliHit {
  ili: string;
  pos: WnPos;
  words: string[];
  gloss: string;
  /** True when a Bengali synset already exists for this ILI. */
  alreadyInBengali: boolean;
}

interface WnIndex {
  version: string;
  synsetCount: number;
  lemmaCount: number;
  synsets: Record<string, { w: string[]; g: string }>;
  lemmas: Record<string, Partial<Record<WnPos, string[]>>>;
}

let cached: WnIndex | null = null;

function loadIndex(): WnIndex {
  if (cached) return cached;
  const candidates = [
    join(process.cwd(), "data", "wordnet21-ili.json"),
    join(process.cwd(), "..", "data", "wordnet21-ili.json"),
  ];
  const path = candidates.find((p) => existsSync(p));
  if (!path) {
    throw new Error(
      "WordNet 2.1 ILI index missing. Run: node scripts/build-wordnet21-ili.mjs"
    );
  }
  cached = JSON.parse(readFileSync(path, "utf8")) as WnIndex;
  return cached;
}

/** True when the code exists in the official WordNet 2.1 registry. */
export function isValidWn21Ili(ili: string): boolean {
  if (!/^\d{8}-[nvar]$/.test(ili)) return false;
  return Boolean(loadIndex().synsets[ili]);
}

export function wn21Synset(ili: string): { words: string[]; gloss: string } | null {
  const syn = loadIndex().synsets[ili];
  return syn ? { words: syn.w, gloss: syn.g } : null;
}

/**
 * Look up WordNet 2.1 synsets by English word and optional POS.
 * Prefers exact lemma matches, then prefix matches. Deduplicates by ILI.
 */
export function searchWn21Ili(
  word: string,
  pos: WnPos | "any" = "any",
  limit = 25,
  alreadyKnown?: (ili: string) => boolean
): IliHit[] {
  const q = word.trim().toLowerCase().replace(/_/g, " ");
  if (q.length < 2) return [];

  const index = loadIndex();
  const seen = new Set<string>();
  const hits: IliHit[] = [];

  const pushIli = (ili: string) => {
    if (seen.has(ili)) return;
    const syn = index.synsets[ili];
    if (!syn) return;
    const iliPos = ili.slice(-1) as WnPos;
    if (pos !== "any" && iliPos !== pos) return;
    seen.add(ili);
    hits.push({
      ili,
      pos: iliPos,
      words: syn.w,
      gloss: syn.g,
      alreadyInBengali: alreadyKnown?.(ili) ?? false,
    });
  };

  // 1. Exact lemma match
  const exact = index.lemmas[q];
  if (exact) {
    for (const p of ["n", "v", "a", "r"] as WnPos[]) {
      if (pos !== "any" && p !== pos) continue;
      for (const ili of exact[p] ?? []) {
        pushIli(ili);
        if (hits.length >= limit) return hits;
      }
    }
  }

  // 2. Prefix / contains match over lemmas (exact already collected)
  const prefix: string[] = [];
  const contains: string[] = [];
  for (const lemma of Object.keys(index.lemmas)) {
    if (lemma === q) continue;
    if (lemma.startsWith(q)) prefix.push(lemma);
    else if (lemma.includes(q)) contains.push(lemma);
  }
  prefix.sort();
  contains.sort();

  for (const lemma of [...prefix, ...contains]) {
    const entry = index.lemmas[lemma];
    if (!entry) continue;
    for (const p of ["n", "v", "a", "r"] as WnPos[]) {
      if (pos !== "any" && p !== pos) continue;
      for (const ili of entry[p] ?? []) {
        pushIli(ili);
        if (hits.length >= limit) return hits;
      }
    }
  }

  return hits;
}

export function wn21Stats(): { version: string; synsetCount: number; lemmaCount: number } {
  const i = loadIndex();
  return {
    version: i.version,
    synsetCount: i.synsetCount,
    lemmaCount: i.lemmaCount,
  };
}
